{"file_path":"src/cache.js","content":"/**
 * Least-recently-used cache with per-entry lifetimes, a byte budget measured
 * by a caller-supplied sizer, and an injectable clock.
 *
 * Recency order is kept in a doubly linked list running alongside the map so
 * that `get`, `set`, `has`, `peek`, and `delete` all do a constant amount of
 * work regardless of how many entries are stored.
 */

/**
 * @typedef {object} CacheNode
 * @property {string} key
 * @property {unknown} value
 * @property {number} bytes
 * @property {number} storedAt
 * @property {number} ttlMs
 * @property {CacheNode|null} prev Toward the least-recently-used end.
 * @property {CacheNode|null} next Toward the most-recently-used end.
 */

function isPlainObjectLike(value) {
  return typeof value === 'object' && value !== null;
}

function isPositiveSafeInteger(value) {
  return Number.isSafeInteger(value) && value > 0;
}

function isNonNegativeNumber(value) {
  return typeof value === 'number' && !Number.isNaN(value) && value >= 0;
}

function isNonNegativeSafeInteger(value) {
  return Number.isSafeInteger(value) && value >= 0;
}

export class LruTtlCache {
  /** @type {Map<string, CacheNode>} */
  #map = new Map();
  /** @type {CacheNode|null} Least-recently-used end. */
  #head = null;
  /** @type {CacheNode|null} Most-recently-used end. */
  #tail = null;

  #maxBytes;
  #ttlMs;
  #clock;
  #sizeOf;
  #onEvict;

  #bytes = 0;
  #hits = 0;
  #misses = 0;
  #evictions = 0;
  #expirations = 0;

  /**
   * @param {object} options Cache options.
   * @param {number} options.maxBytes Byte budget; a positive safe integer.
   * @param {number} [options.ttlMs] Default lifetime, `Infinity` by default.
   * @param {() => number} [options.clock] Millisecond clock, `Date.now` by default.
   * @param {(value: unknown, key: string) => number} [options.sizeOf] Sizer, one byte per entry by default.
   * @param {(key: string, value: unknown, reason: string) => void} [options.onEvict] Removal callback.
   */
  constructor(options) {
    if (!isPlainObjectLike(options)) {
      throw new TypeError('options must be an object');
    }
    const { maxBytes, ttlMs = Infinity, clock = Date.now, sizeOf = () => 1, onEvict = () => {} } = options;

    if (!isPositiveSafeInteger(maxBytes)) {
      throw new TypeError('maxBytes must be a positive integer');
    }
    if (!isNonNegativeNumber(ttlMs)) {
      throw new TypeError('ttlMs must be a non-negative number');
    }
    if (typeof clock !== 'function') {
      throw new TypeError('clock must be a function');
    }
    if (typeof sizeOf !== 'function') {
      throw new TypeError('sizeOf must be a function');
    }
    if (typeof onEvict !== 'function') {
      throw new TypeError('onEvict must be a function');
    }

    this.#maxBytes = maxBytes;
    this.#ttlMs = ttlMs;
    this.#clock = clock;
    this.#sizeOf = sizeOf;
    this.#onEvict = onEvict;
  }

  /** @returns {number} Byte budget the cache was built with. */
  get capacity() {
    return this.#maxBytes;
  }

  /** @returns {number} Number of stored entries, expired ones included. */
  get size() {
    return this.#map.size;
  }

  /** @returns {number} Bytes charged by the stored entries. */
  get bytes() {
    return this.#bytes;
  }

  /**
   * Unlinks a node from the recency list.
   * @param {CacheNode} node Node to unlink.
   * @returns {void}
   */
  #unlink(node) {
    const { prev, next } = node;
    if (prev !== null) {
      prev.next = next;
    } else {
      this.#head = next;
    }
    if (next !== null) {
      next.prev = prev;
    } else {
      this.#tail = prev;
    }
    node.prev = null;
    node.next = null;
  }

  /**
   * Appends a node at the most-recently-used end.
   * @param {CacheNode} node Node to append.
   * @returns {void}
   */
  #appendTail(node) {
    node.prev = this.#tail;
    node.next = null;
    if (this.#tail !== null) {
      this.#tail.next = node;
    } else {
      this.#head = node;
    }
    this.#tail = node;
  }

  /**
   * Moves an already-linked node to the most-recently-used end.
   * @param {CacheNode} node Node to promote.
   * @returns {void}
   */
  #touch(node) {
    if (this.#tail === node) return;
    this.#unlink(node);
    this.#appendTail(node);
  }

  /**
   * Removes a node from the map and list, updates bytes, and optionally
   * reports it through `onEvict` and the counters.
   * @param {CacheNode} node Node to remove.
   * @param {string|null} reason `expire`, `size`, `replace`, or `null` for silent removal.
   * @returns {void}
   */
  #removeNode(node, reason) {
    this.#unlink(node);
    this.#map.delete(node.key);
    this.#bytes -= node.bytes;
    if (reason !== null) {
      if (reason === 'expire') this.#expirations += 1;
      if (reason === 'size') this.#evictions += 1;
      this.#onEvict(node.key, node.value, reason);
    }
  }

  /**
   * Reports whether a node's lifetime has fully elapsed.
   * @param {CacheNode} node Node to check.
   * @param {number} now Current clock reading.
   * @returns {boolean} True when expired.
   */
  #isExpired(node, now) {
    return now - node.storedAt >= node.ttlMs;
  }

  /**
   * Validates a cache key.
   * @param {unknown} key Candidate key.
   * @returns {void}
   */
  #checkKey(key) {
    if (typeof key !== 'string') {
      throw new TypeError('key must be a string');
    }
  }

  /**
   * Looks up a live entry, removing and reporting it if it has expired.
   * @param {string} key Cache key.
   * @returns {CacheNode|undefined} The live node, or undefined when absent or expired.
   */
  #getLive(key) {
    const node = this.#map.get(key);
    if (node === undefined) return undefined;
    const now = this.#clock();
    if (this.#isExpired(node, now)) {
      this.#removeNode(node, 'expire');
      return undefined;
    }
    return node;
  }

  /**
   * Stores a value, replacing any entry already under the key.
   * @param {string} key Cache key.
   * @param {unknown} value Value to store.
   * @param {{ttlMs?: number}} [options] Per-entry lifetime override.
   * @returns {boolean} False when the value alone exceeds the byte budget.
   */
  set(key, value, options = {}) {
    this.#checkKey(key);
    if (!isPlainObjectLike(options)) {
      throw new TypeError('options must be an object');
    }
    const { ttlMs = this.#ttlMs } = options;
    if (!isNonNegativeNumber(ttlMs)) {
      throw new TypeError('ttlMs must be a non-negative number');
    }

    const sized = this.#sizeOf(value, key);
    if (!isNonNegativeSafeInteger(sized)) {
      throw new TypeError('sizeOf must return a non-negative safe integer');
    }

    const existing = this.#map.get(key);
    if (existing !== undefined) {
      this.#removeNode(existing, 'replace');
    }

    if (sized > this.#maxBytes) {
      return false;
    }

    const now = this.#clock();
    /** @type {CacheNode} */
    const node = {
      key,
      value,
      bytes: sized,
      storedAt: now,
      ttlMs,
      prev: null,
      next: null,
    };
    this.#map.set(key, node);
    this.#appendTail(node);
    this.#bytes += sized;

    while (this.#bytes > this.#maxBytes) {
      const victim = this.#head;
      if (victim === null) break;
      const reason = this.#isExpired(victim, now) ? 'expire' : 'size';
      this.#removeNode(victim, reason);
    }

    return true;
  }

  /**
   * Reads a value and marks the entry most-recently used.
   * @param {string} key Cache key.
   * @returns {unknown} Stored value, or undefined when absent or expired.
   */
  get(key) {
    this.#checkKey(key);
    const node = this.#getLive(key);
    if (node === undefined) {
      this.#misses += 1;
      return undefined;
    }
    this.#touch(node);
    this.#hits += 1;
    return node.value;
  }

  /**
   * Reads a value without changing recency or hit counters.
   * @param {string} key Cache key.
